import { clsx, type ClassValue } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

const twMerge = extendTailwindMerge({
  extend: { theme: { radius: ["control", "surface", "overlay"], shadow: ["overlay"] } },
});

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

"use client";

import {
  useLayoutEffect,
  useRef,
  useState,
  type ComponentProps,
  type ReactNode,
} from "react";
import { cn } from "./lib/cn";
import "./skeleton.css";

const widths = ["100%", "94%", "78%", "88%", "66%", "84%"];

export function Skeleton({
  label = "Loading content",
  lines = 3,
  avatar = false,
  loading = true,
  children,
  className,
  ...props
}: Omit<ComponentProps<"div">, "children"> & {
  label?: string;
  lines?: number;
  avatar?: boolean;
  loading?: boolean;
  children?: ReactNode;
}) {
  const count = Math.min(6, Math.max(1, Math.round(lines)));
  const placeholder = useRef<HTMLDivElement>(null);
  const content = useRef<HTMLDivElement>(null);
  const [height, setHeight] = useState<number>();
  const hasContent = children != null;

  useLayoutEffect(() => {
    const node = (loading ? placeholder : content).current;
    if (!hasContent || !node) return;
    setHeight(node.getBoundingClientRect().height);
  }, [avatar, count, hasContent, loading, children]);

  const blocks = (
    <div ref={placeholder} data-slot="skeleton-placeholder" className="flex gap-3">
      {avatar && (
        <span
          data-slot="skeleton-block"
          className="size-8 shrink-0 rounded-surface"
          style={{ animationDelay: "0ms" }}
        />
      )}
      <span className="flex min-w-0 flex-1 flex-col justify-center gap-2">
        {Array.from({ length: count }, (_, index) => (
          <span
            key={index}
            data-slot="skeleton-block"
            className="block h-2.5 max-w-full"
            style={{
              width: widths[(index + (avatar ? 1 : 0)) % widths.length],
              animationDelay: `calc(${index + (avatar ? 1 : 0)} * var(--delay-stagger))`,
            }}
          />
        ))}
      </span>
    </div>
  );

  if (!hasContent) {
    return (
      <div
        role="status"
        aria-busy="true"
        aria-label={label}
        data-slot="skeleton"
        data-loading="true"
        className={className}
        {...props}
      >
        {blocks}
      </div>
    );
  }

  return (
    <div
      role="status"
      aria-busy={loading || undefined}
      aria-label={loading ? label : undefined}
      data-slot="skeleton"
      data-loading={loading}
      data-has-content="true"
      className={cn("relative overflow-hidden", className)}
      style={height != null ? { height } : undefined}
      {...props}
    >
      {blocks}
      <div ref={content} data-slot="skeleton-content">
        {children}
      </div>
    </div>
  );
}

/* skeleton.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  [data-slot="skeleton"][data-has-content="true"] {
    transition: height var(--duration-normal) var(--ease-settle);
  }
  [data-slot="skeleton"][data-has-content="true"] [data-slot="skeleton-placeholder"],
  [data-slot="skeleton"][data-has-content="true"] [data-slot="skeleton-content"] {
    position: absolute;
    inset-inline: 0;
    top: 0;
    transition:
      opacity var(--duration-normal) var(--ease-out),
      transform var(--duration-normal) var(--ease-settle);
  }
  [data-slot="skeleton"][data-loading="true"] [data-slot="skeleton-content"] {
    opacity: 0;
    transform: translateY(var(--motion-enter-distance));
    pointer-events: none;
  }
  [data-slot="skeleton"][data-loading="false"] [data-slot="skeleton-placeholder"] {
    opacity: 0;
    pointer-events: none;
  }
  [data-slot="skeleton-block"] {
    border-radius: var(--radius-control);
    background: var(--muted);
    animation: caliper-skeleton-pulse var(--duration-skeleton) var(--ease-in-out) infinite;
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="skeleton"],
    [data-slot="skeleton-placeholder"],
    [data-slot="skeleton-content"] {
      transition: none;
    }
    [data-slot="skeleton-block"] {
      animation: none;
      transition: none;
      transform: none;
    }
  }
}
